/// Unit-test default. Mirrors the auto-generated curve at a slightly higher
/// constant offset so tests can assert "weight grows with n" without
/// depending on hardware-specific picosecond values.
impl WeightInfo for () {
    fn settle_batch_atomic(n: u32) -> Weight {
        Weight::from_parts(
            50_000_000u64.saturating_add((n as u64).saturating_mul(17_000_000)),
            321_487u64.saturating_add((n as u64).saturating_mul(3_119)),
        )
    }
    fn post_settlement_bond() -> Weight {
        Weight::from_parts(500_000_000, 0)
    }
    fn slash_bad_settlement_evidence() -> Weight {
        Weight::from_parts(500_000_000, 0)
    }
    fn release_settlement_bond() -> Weight {
        Weight::from_parts(500_000_000, 0)
    }
    fn request_settle() -> Weight {
        Weight::from_parts(700_000_000, 7_000)
    }
    fn request_batch_settle(n: u32) -> Weight {
        Weight::from_parts(
            50_000_000u64.saturating_add((n as u64).saturating_mul(650_000_000)),
            (n as u64).saturating_mul(7_000),
        )
    }
    fn supersede_settlement_request() -> Weight {
        Weight::from_parts(620_000_000, 9_000)
    }
}
